import string

def rotate_string(s):
    """Helper function to rotate the alphabet based on the rotation by two times the index."""
    rotated = []
    for char in s:
        if char.isalpha():
            shift = 2 * (s.index(char) // 26)
            base = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.index(char.upper())
            rotated_char = chr((base + shift) % 26 + (0 if char.isupper() else 26))
            if char.islower():
                rotated.append(rotated_char.lower())
            else:
                rotated.append(rotated_char)
        else:
            rotated.append(char)
    return ''.join(rotated)

def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt('hi') returns 'lm'
    encrypt('asdfghjkl') returns 'ewhjklnop'
    encrypt('gf') returns 'kj'
    encrypt('et') returns 'ix'
    """
    return rotate_string(s)
