    closest_vowel = ""
    for i in range(len(word) - 2, -1, -1):
        if word[i] in vowels:
            closest_vowel = word[i]
            for j in range(i - 1, -1, -1):
                if word[j] not in vowels:
                    break
            for j in range(i + 1, len(word)):
                if word[j] not in vowels:
                    break
            return closest_vowel
