import numpy as np

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    planets_dict = {planet: i for i, planet in enumerate(planets)}

    try:
        index1 = planets_dict[planet1]
        index2 = planets_dict[planet2]

        if index1 == index2 or index1 == 0 or index2 == len(planets) - 1:
            return tuple()

        # Sort planets by their index (sun is 0th, Neptune is last)
        ordered_planets = sorted(planets[index1:index2+1], key=lambda planet: planets_dict[planet])

        return tuple(ordered_planets)
    except KeyError:
        return tuple()
