import math

def double_the_difference(lst):
    # Convert list to a set to ignore duplicate elements
    lst = set(lst)

    # Filter out non-integer and negative elements
    lst = {x for x in lst if isinstance(x, int) and x >= 0}

    # Calculate the sum of squares of odd numbers
    return sum(math.pow(x, 2) for x in lst if x % 2 != 0)
